// Sanitize inputs & add WhatsApp HR link
const body = $json.body;
const hrPhone = '923161236343';
const waUrl = `https://wa.me/${hrPhone}?text=Application%20Received%20for%20${encodeURIComponent(body.candidateName)}`;

return { json: { candidateEmail: body.candidateEmail, candidateName: body.candidateName, candidatePhone: body.candidatePhone, hrWhatsApp: hrPhone, whatsappUrl: waUrl, jobId: body.jobId } };
